minimal_vertex_shader_glsl.code:
#version 330 core
layout(location = 0) in vec3 aPos;
uniform mat4 uMVP;
void main() {
    gl_Position = uMVP * vec4(aPos, 1.0);
}

minimal_fragment_shader_glsl.code:
#version 330 core
out vec4 FragColor;
void main() {
    FragColor = vec4(1.0, 0.0, 0.0, 1.0);
}

simple_graphics_loop_concept.code:
while (window.isOpen()) {
    processInput();
    renderer.clear(Color(0.1f, 0.1f, 0.2f, 1.0f));
    shader.setUniform("uMVP", camera.getMVP());
    mesh.bind();
    renderer.draw(mesh.getIndexCount());
    window.swapBuffers();
}
